      ro: ["Negevul ocupă aproximativ 13.000 km² din teritoriul israelian.", "Craterele de eroziune de tip 'machtesh' nu se găsesc nicăieri altundeva.", "Altitudinea maximă este atinsă pe Muntele Ramon la 1.037 m.", "Orașul antic Avdat este sit al Patrimoniului Mondial UNESCO.", "Pluviometria medie în sudul extrem este sub 30 mm pe an.", "Regiunea este împărțită în Negevul de Nord, Central și de Sud."],
      en: ["The Negev spans 13,000 square kilometers, over half of Israel's area.", "Makhtesh Ramon is the largest erosion crater on Earth at 40 km long.", "The region is home to the world's most advanced desert drip irrigation.", "Mount Ramon is the highest peak in the Negev at 1,037 meters.", "The Nabataean city of Shivta shows complex ancient water engineering.", "Winter flash floods in the Negev are a major force of geological erosion."],
      es: ["El Néguev abarca una superficie de unos 13.000 km².", "El Makhtesh Ramon es el cráter de erosión más grande del mundo con 40 km de largo.", "La ciudad de Beerseba es considerada la 'capital del Néguev'.", "La montaña más alta de la región es el Monte Ramon con 1.037 metros.", "La Ruta del Incienso de los nabateos en el Néguev es Patrimonio de la Humanidad de la UNESCO.", "Las precipitaciones en el sur pueden ser inferiores a 25 mm por año."],
