      en: ["The valley sits at the lowest point on Earth (-430 meters).", "The total length of the valley is approximately 105 kilometers.", "The Jordan River is the only permanent water source in the region.", "Jericho, located in the valley, is among the world's oldest cities.", "The valley is a major agricultural hub for the state of Israel.", "About 500 million migratory birds fly over the valley each year."],
      es: ["El valle se encuentra en el punto más bajo de la superficie terrestre (-430 m).", "La longitud total del valle es de unos 105 kilómetros.", "El Jordán es la única fuente de agua permanente en la región.", "Jericó, en el valle del Jordán, es considerada una de las ciudades más antiguas del mundo.", "El valle es un importante productor agrícola para Israel.", "Alrededor de 500 millones de aves migratorias cruzan el valle del Jordán anualmente."],
      pt: ["O vale situa-se no ponto mais baixo da superfície terrestre (-430 m).", "O comprimento total do vale é de cerca de 105 quilómetros.", "O Jordão é a única fonte de água permanente na região.", "Jericó, no vale do Jordão, é considerada uma das cidades mais antigas do mundo.", "O vale é um importante produtor agrícola para Israel.", "Anualmente, cerca de 500 milhões de aves migratórias atravessam o vale do Jordão."],
      fr: ["La vallée se situe au point le plus bas de la surface terrestre (-430 m).", "La longueur totale de la vallée est d'environ 105 kilomètres.", "Le Jourdain est la seule source d'eau permanente de la région.", "Jéricho, dans la vallée du Jourdain, est considérée comme l'une des plus anciennes villes du monde.", "La vallée est un producteur agricole majeur pour Israël.", "Chaque année, environ 500 millions d'oiseaux migrateurs survolent la vallée du Jourdain."],
